import{At as e,Mt as t,Qt as n,lt as r}from"./chunks/framework.DwOUwJQP.js";var i=JSON.parse(`{"title":"MCP 协议","description":"MCP 是一种用于连接 AI 模型与外部数据源、工具和服务的开放协议。","frontmatter":{"title":"MCP 协议","date":"2025-04-01T21:25:00.000Z","tags":["AI"],"description":"MCP 是一种用于连接 AI 模型与外部数据源、工具和服务的开放协议。"},"headers":[],"relativePath":"blogs/ai/concept/MCP协议.md","filePath":"blogs/ai/concept/MCP协议.md","lastUpdated":1787475818000}`),a={name:`blogs/ai/concept/MCP协议.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h2 id="什么是mcp协议" tabindex="-1">什么是MCP协议？ <a class="header-anchor" href="#什么是mcp协议" aria-label="Permalink to “什么是MCP协议？”">​</a></h2><p>定义</p><p>MCP（Model Context Protocol，模型上下文协议），2024年11月底，由 Anthropic 推出的一种开放标准，旨在统一大型语言模型（LLM）与外部数据源和工具之间的通信协议。MCP的主要目的在于解决当前 AI 模型因数据孤岛限制而无法充分发挥潜力的难题，MCP使AI应用能够安全地访问和操作本地及远程数据，为 AI 应用提供了连接万物的接口。</p><h3 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to “价值”">​</a></h3><p>在过去，为了让大模型等 AI 应用使用我们的数据，要么复制粘贴，要么上传下载，非常麻烦。</p><p>即使是最强大模型也会受到数据隔离的限制，形成信息孤岛，要做出更强大的模型，每个新数据源都需要自己重新定制实现，使真正互联的系统难以扩展，存在很多的局限性。</p><p>现在MCP可以直接在AI与数据（包括本地数据和互联网数据）之间架起一座桥梁，通过MCP服务器和MCP客户端，大家只要都遵循这套协议，就能实现“万物互联”。</p><p>有了MCP，可以和数据和文件系统、开发工具、Web和浏览器自动化、生产力和通信、各种社区生态能力全部集成，实现强大的协作工作能力。</p><h3 id="mcp-与-function-calling-区别" tabindex="-1">MCP 与 Function Calling 区别 <a class="header-anchor" href="#mcp-与-function-calling-区别" aria-label="Permalink to “MCP 与 Function Calling 区别”">​</a></h3><ul><li>MCP（Model Context Protocol），模型上下文协议</li><li>Function Calling，函数调用</li></ul><p>这两种技术都旨在增强 AI 模型与外部数据的交互能力，但MCP不止可以增强AI模型，还可以是其他应用系统。</p><table tabindex="0"><thead><tr><th style="text-align:center;">类别</th><th style="text-align:center;">MCP（Model Context Protocol）</th><th style="text-align:center;">Function Calling</th></tr></thead><tbody><tr><td style="text-align:center;">性质</td><td style="text-align:center;">协议</td><td style="text-align:center;">功能</td></tr><tr><td style="text-align:center;">范围</td><td style="text-align:center;">通用（多数据源、多功能）</td><td style="text-align:center;">特定场景（单一数据源或功能）</td></tr><tr><td style="text-align:center;">目标</td><td style="text-align:center;">统一接口，实现互操作</td><td style="text-align:center;">扩展模型能力</td></tr><tr><td style="text-align:center;">实现</td><td style="text-align:center;">基于标准协议</td><td style="text-align:center;">依赖特定模型实现</td></tr><tr><td style="text-align:center;">开发复杂度</td><td style="text-align:center;">低：通过统一协议实现多源兼容</td><td style="text-align:center;">高：需要为每个任务单独开发函数</td></tr><tr><td style="text-align:center;">复用性</td><td style="text-align:center;">高：一次开发，可多场景使用</td><td style="text-align:center;">低：函数通常为特定设计</td></tr><tr><td style="text-align:center;">灵活性</td><td style="text-align:center;">高：支持动态适配和扩展</td><td style="text-align:center;">低：功能扩展需要额外开发</td></tr><tr><td style="text-align:center;">常见场景</td><td style="text-align:center;">复杂场景，如跨平台数据访问与整合</td><td style="text-align:center;">简单任务，如天气查询，翻译等</td></tr></tbody></table><h3 id="数据安全性" tabindex="-1"><strong>数据安全性</strong> <a class="header-anchor" href="#数据安全性" aria-label="Permalink to “数据安全性”">​</a></h3><p>这样一个理想的“万物互联”生态系统看着很让人着迷。</p><p>但是大家是不是担心通过 MCP Server 暴露出来的数据会泄露或被非法访问，这个头疼的问题 MCP 也考虑到了。</p><p>MCP 通过标准化的数据访问接口，大大减少了直接接触敏感数据的环节，降低了数据泄露的风险。</p><p>还有，MCP 内置了安全机制，确保只有经过验证的请求才能访问特定资源，相当于在数据安全又加上了一道防线。同时，MCP协议还支持多种加密算法，以确保数据在传输过程中的安全性。</p><p>例如，MCP 服务器自己控制资源，不需要将 API 密钥等敏感信息提供给 LLM 提供商。这样一来，即使 LLM 提供商受到攻击，攻击者也无法获取到这些敏感信息。</p><h3 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to “工作原理”">​</a></h3><p>MCP 协议采用了一种独特的架构设计，它将 LLM 与资源之间的通信划分为三个主要部分：客户端、服务器和资源。</p><p>客户端负责发送请求给 MCP 服务器，服务器则将这些请求转发给相应的资源。这种分层的设计使得 MCP 协议能够更好地控制访问权限，确保只有经过授权的用户才能访问特定的资源。</p><p>工作基本流程</p><ul><li>初始化连接：客户端向服务器发送连接请求，建立通信通道。</li><li>发送请求：客户端根据需求构建请求消息，并发送给服务器。</li><li>处理请求：服务器接收到请求后，解析请求内容，执行相应操作（如查询数据库、读取文件等）。</li><li>返回结果：服务器将处理结果封装成响应消息，发送回客户端。</li><li>断开连接：任务完成后，客户端可以主动关闭连接或等待服务器超时关闭。</li></ul><h3 id="mcp-核心架构" tabindex="-1">MCP 核心架构 <a class="header-anchor" href="#mcp-核心架构" aria-label="Permalink to “MCP 核心架构”">​</a></h3><p>MCP 遵循客户端-服务器架构（client-server），其中包含以下几个核心概念：</p><ul><li>MCP 主机（MCP Hosts）：发起请求的 LLM 应用程序（例如 <a href="https://zhida.zhihu.com/search?content_id=254488153&amp;content_type=Article&amp;match_order=1&amp;q=Claude+Desktop&amp;zd_token=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJ6aGlkYV9zZXJ2ZXIiLCJleHAiOjE3NDM2ODY2MjcsInEiOiJDbGF1ZGUgRGVza3RvcCIsInpoaWRhX3NvdXJjZSI6ImVudGl0eSIsImNvbnRlbnRfaWQiOjI1NDQ4ODE1MywiY29udGVudF90eXBlIjoiQXJ0aWNsZSIsIm1hdGNoX29yZGVyIjoxLCJ6ZF90b2tlbiI6bnVsbH0.p7Bj8_teKxSQAVQ3EQ-2GAgNOB_qn9L5WS3eQYnU_IM&amp;zhida_source=entity" target="_blank" rel="noreferrer">Claude Desktop</a>、IDE 或 AI 工具）。</li><li>MCP 客户端（MCP Clients）：在主机程序内部，与 MCP server 保持 1:1 的连接。</li><li>MCP 服务器（MCP Servers）：为 MCP client 提供上下文、工具和 prompt 信息。</li><li>本地资源（Local Resources）：本地计算机中可供 MCP server 安全访问的资源（例如文件、数据库）。</li><li>远程资源（Remote Resources）：MCP server 可以连接到的远程资源（例如通过 API）。</li></ul><h3 id="mcp-client" tabindex="-1"><strong>MCP Client</strong> <a class="header-anchor" href="#mcp-client" aria-label="Permalink to “MCP Client”">​</a></h3><p>MCP client 充当 LLM 与 MCP server 之间的桥梁，MCP client 的工作流程如下：</p><ul><li>MCP client 首先从 MCP server 获取可用的工具列表。</li><li>将用户的查询连同工具描述通过 function calling 一起发送给 LLM。</li><li>LLM 决定是否需要使用工具以及使用哪些工具。</li><li>如果需要使用工具，MCP client 会通过 MCP server 执行相应的工具调用。</li><li>工具调用的结果会被发送回 LLM。</li><li>LLM 基于所有信息生成自然语言响应。</li><li>最后将响应展示给用户。</li></ul><p>Claude Desktop 和Cursor都支持了MCP Server接入能力，它们就是作为 MCP client来连接某个MCP Server感知和实现调用。</p><h3 id="mcp-server" tabindex="-1"><strong>MCP Server</strong> <a class="header-anchor" href="#mcp-server" aria-label="Permalink to “MCP Server”">​</a></h3><p>MCP server 是 MCP 架构中的关键组件，它可以提供 3 种主要类型的功能：</p><ul><li>资源（Resources）：类似文件的数据，可以被客户端读取，如 API 响应或文件内容。</li><li>工具（Tools）：可以被 LLM 调用的函数（需要用户批准）。</li><li>提示（Prompts）：预先编写的模板，帮助用户完成特定任务。</li></ul><p>这些功能使 MCP server 能够为 AI 应用提供丰富的上下文信息和操作能力，从而增强 LLM 的实用性和灵活性。</p><p>你可以在 MCP Servers Repository 和 Awesome MCP Servers 这两个 repo 中找到许多由社区实现的 MCP server。使用 TypeScript 编写的 MCP server 可以通过 npx 命令来运行，使用 Python 编写的 MCP server 可以通过 uvx 命令来运行。</p><h3 id="通信机制" tabindex="-1"><strong>通信机制</strong> <a class="header-anchor" href="#通信机制" aria-label="Permalink to “通信机制”">​</a></h3><p>MCP 协议支持两种主要的通信机制：基于标准输入输出的本地通信和基于<a href="https://zhida.zhihu.com/search?content_id=254488153&amp;content_type=Article&amp;match_order=1&amp;q=SSE&amp;zd_token=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJ6aGlkYV9zZXJ2ZXIiLCJleHAiOjE3NDM2ODY2MjcsInEiOiJTU0UiLCJ6aGlkYV9zb3VyY2UiOiJlbnRpdHkiLCJjb250ZW50X2lkIjoyNTQ0ODgxNTMsImNvbnRlbnRfdHlwZSI6IkFydGljbGUiLCJtYXRjaF9vcmRlciI6MSwiemRfdG9rZW4iOm51bGx9.6I6gMkw-ygEyn6sR7YNjI71mZnfr9dS3Js_vkenfzcE&amp;zhida_source=entity" target="_blank" rel="noreferrer">SSE</a>（<a href="https://link.zhihu.com/?target=https%3A//en.wikipedia.org/wiki/Server-sent_events" target="_blank" rel="noreferrer">Server-Sent Events</a>）的远程通信。</p><p>这两种机制都使用 <a href="https://link.zhihu.com/?target=https%3A//www.jsonrpc.org/specification" target="_blank" rel="noreferrer">JSON-RPC 2.0</a> 格式进行消息传输，确保了通信的标准化和可扩展性。</p><ul><li>本地通信<strong>：</strong>通过 stdio 传输数据，适用于在同一台机器上运行的客户端和服务器之间的通信。</li><li>远程通信<strong>：</strong>利用 SSE 与 HTTP 结合，实现跨网络的实时数据传输，适用于需要访问远程资源或分布式部署的场景。</li></ul><h2 id="二、mcp的功能与应用" tabindex="-1">二、MCP的功能与应用： <a class="header-anchor" href="#二、mcp的功能与应用" aria-label="Permalink to “二、MCP的功能与应用：”">​</a></h2><h3 id="如何使用-mcp" tabindex="-1">如何使用 MCP <a class="header-anchor" href="#如何使用-mcp" aria-label="Permalink to “如何使用 MCP”">​</a></h3><p>如果还没有尝试过如何使用 MCP 的话，我们可以考虑用 Cursor，Claude Desktop 或者 Cline 来体验一下。</p><p>当然，我们并不需要自己开发 MCP Servers，MCP 的好处就是通用、标准，所以开发者并不需要重复造轮子（但是学习可以重复造轮子）。</p><p>首先推荐的是官方组织的一些 Server：<a href="https://link.zhihu.com/?target=https%3A//github.com/modelcontextprotocol/servers" target="_blank" rel="noreferrer">官方的 MCP Server 列表</a>。</p><h3 id="mcp的功能" tabindex="-1">MCP的功能 <a class="header-anchor" href="#mcp的功能" aria-label="Permalink to “MCP的功能”">​</a></h3><p>MCP通过引入多样化的MCP Server能力，显著增强了AI工具的功能，例如我们常用的Cursor和Claude。以下是一些官方参考服务器，展示了MCP的核心功能和SDK的应用：</p><p>数据与文件系统：</p><ul><li>文件系统：提供安全文件操作，带可配置的访问控制。</li><li><a href="https://zhida.zhihu.com/search?content_id=254488153&amp;content_type=Article&amp;match_order=1&amp;q=PostgreSQL&amp;zd_token=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJ6aGlkYV9zZXJ2ZXIiLCJleHAiOjE3NDM2ODY2MjcsInEiOiJQb3N0Z3JlU1FMIiwiemhpZGFfc291cmNlIjoiZW50aXR5IiwiY29udGVudF9pZCI6MjU0NDg4MTUzLCJjb250ZW50X3R5cGUiOiJBcnRpY2xlIiwibWF0Y2hfb3JkZXIiOjEsInpkX3Rva2VuIjpudWxsfQ.oenjJKUnQeCfpsrT5lqv93YG57u54NxrRltByDpSKG4&amp;zhida_source=entity" target="_blank" rel="noreferrer">PostgreSQL</a>：提供只读数据库访问，具备架构检查功能。</li><li><a href="https://zhida.zhihu.com/search?content_id=254488153&amp;content_type=Article&amp;match_order=1&amp;q=SQLite&amp;zd_token=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJ6aGlkYV9zZXJ2ZXIiLCJleHAiOjE3NDM2ODY2MjcsInEiOiJTUUxpdGUiLCJ6aGlkYV9zb3VyY2UiOiJlbnRpdHkiLCJjb250ZW50X2lkIjoyNTQ0ODgxNTMsImNvbnRlbnRfdHlwZSI6IkFydGljbGUiLCJtYXRjaF9vcmRlciI6MSwiemRfdG9rZW4iOm51bGx9.-vZBTrnc3KBxaNdPrptrVrQ7Wge-blQr1uPouaT35bU&amp;zhida_source=entity" target="_blank" rel="noreferrer">SQLite</a>：支持数据库交互和商业智能功能。</li><li>Google Drive：实现Google Drive的文件访问和搜索功能。</li></ul><p>开发工具：</p><ul><li>Git：工具用于读取、搜索和操作Git仓库。</li><li>GitHub：集成仓库管理、文件操作和GitHub API。</li><li><a href="https://zhida.zhihu.com/search?content_id=254488153&amp;content_type=Article&amp;match_order=1&amp;q=GitLab&amp;zd_token=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJ6aGlkYV9zZXJ2ZXIiLCJleHAiOjE3NDM2ODY2MjcsInEiOiJHaXRMYWIiLCJ6aGlkYV9zb3VyY2UiOiJlbnRpdHkiLCJjb250ZW50X2lkIjoyNTQ0ODgxNTMsImNvbnRlbnRfdHlwZSI6IkFydGljbGUiLCJtYXRjaF9vcmRlciI6MSwiemRfdG9rZW4iOm51bGx9.itRmUqOrBcpw0Z781WjyKwaX13NZthNkcgL1_bU9YOs&amp;zhida_source=entity" target="_blank" rel="noreferrer">GitLab</a>：支持项目管理的GitLab API集成。</li><li>Sentry：从<a href="https://link.zhihu.com/?target=http%3A//Sentry.io" target="_blank" rel="noreferrer">http://Sentry.io</a>获取并分析问题。</li></ul><p>网络与浏览器自动化：</p><ul><li>Brave Search：利用Brave的搜索API进行网络和本地搜索。</li><li>Fetch：为LLM优化的网络内容获取和转换。</li><li><a href="https://zhida.zhihu.com/search?content_id=254488153&amp;content_type=Article&amp;match_order=1&amp;q=Puppeteer&amp;zd_token=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJ6aGlkYV9zZXJ2ZXIiLCJleHAiOjE3NDM2ODY2MjcsInEiOiJQdXBwZXRlZXIiLCJ6aGlkYV9zb3VyY2UiOiJlbnRpdHkiLCJjb250ZW50X2lkIjoyNTQ0ODgxNTMsImNvbnRlbnRfdHlwZSI6IkFydGljbGUiLCJtYXRjaF9vcmRlciI6MSwiemRfdG9rZW4iOm51bGx9.8dHNa0xKzlXKhN2ouDmkcz4z7NbgaszUOzabM5nqp9I&amp;zhida_source=entity" target="_blank" rel="noreferrer">Puppeteer</a>：提供浏览器自动化和网页抓取功能。</li></ul><p>生产力和通信：</p><ul><li><a href="https://zhida.zhihu.com/search?content_id=254488153&amp;content_type=Article&amp;match_order=1&amp;q=Slack&amp;zd_token=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJ6aGlkYV9zZXJ2ZXIiLCJleHAiOjE3NDM2ODY2MjcsInEiOiJTbGFjayIsInpoaWRhX3NvdXJjZSI6ImVudGl0eSIsImNvbnRlbnRfaWQiOjI1NDQ4ODE1MywiY29udGVudF90eXBlIjoiQXJ0aWNsZSIsIm1hdGNoX29yZGVyIjoxLCJ6ZF90b2tlbiI6bnVsbH0.dzjsJAUuC0exfVqNW5OX8---T58ftflNaitTV1Hwcxw&amp;zhida_source=entity" target="_blank" rel="noreferrer">Slack</a>：支持频道管理和消息功能。</li><li>Google Maps：提供位置服务、路线和地点详情。</li><li>Memory：基于知识图谱的持久记忆系统。</li></ul><p>AI与专业工具：</p><ul><li><a href="https://zhida.zhihu.com/search?content_id=254488153&amp;content_type=Article&amp;match_order=1&amp;q=EverArt&amp;zd_token=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJ6aGlkYV9zZXJ2ZXIiLCJleHAiOjE3NDM2ODY2MjcsInEiOiJFdmVyQXJ0IiwiemhpZGFfc291cmNlIjoiZW50aXR5IiwiY29udGVudF9pZCI6MjU0NDg4MTUzLCJjb250ZW50X3R5cGUiOiJBcnRpY2xlIiwibWF0Y2hfb3JkZXIiOjEsInpkX3Rva2VuIjpudWxsfQ.2vbk61IBVLCw5dpZZynh6iRPQiahBCN1cuK06w5ogpo&amp;zhida_source=entity" target="_blank" rel="noreferrer">EverArt</a>：使用多种模型进行AI图像生成。</li><li>Sequential Thinking：通过思维序列进行动态问题解决。</li><li><a href="https://zhida.zhihu.com/search?content_id=254488153&amp;content_type=Article&amp;match_order=1&amp;q=AWS+KB+Retrieval&amp;zd_token=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJ6aGlkYV9zZXJ2ZXIiLCJleHAiOjE3NDM2ODY2MjcsInEiOiJBV1MgS0IgUmV0cmlldmFsIiwiemhpZGFfc291cmNlIjoiZW50aXR5IiwiY29udGVudF9pZCI6MjU0NDg4MTUzLCJjb250ZW50X3R5cGUiOiJBcnRpY2xlIiwibWF0Y2hfb3JkZXIiOjEsInpkX3Rva2VuIjpudWxsfQ.fMDPky9xfr66CLPzY0dTqWEW6sOQUc0ptMPBfXheiVc&amp;zhida_source=entity" target="_blank" rel="noreferrer">AWS KB Retrieval</a>：使用Bedrock Agent Runtime从AWS知识库检索。</li></ul><p>官方集成工具：</p><ul><li>Axiom：使用自然语言查询和分析日志、跟踪和事件数据。</li><li>Browserbase：云端自动化浏览器交互。</li><li>Cloudflare：在Cloudflare开发者平台上部署和管理资源。</li><li>E2B：在安全的云沙箱中执行代码。</li><li>Neon：与Neon无服务器Postgres平台交互。</li><li>Obsidian Markdown Notes：读取和搜索Obsidian知识库中的Markdown笔记。</li><li>Qdrant：使用Qdrant向量搜索引擎实现语义记忆。</li><li>Raygun：访问崩溃报告和监控数据。</li><li>Search1API：统一的API用于搜索、爬虫和网站地图。</li><li>Tinybird：与Tinybird无服务器ClickHouse平台交互。</li></ul><p>集成工具：</p><ul><li>Docker：管理容器、镜像、卷和网络。</li><li>Kubernetes：管理pod、部署和服务。</li><li>Linear：项目管理和问题跟踪。</li><li>Snowflake：与Snowflake数据库交互。</li><li>Spotify：控制Spotify播放和管理播放列表。</li><li>Todoist：任务管理集成。</li></ul><h2 id="mcp-如何工作" tabindex="-1">MCP 如何工作 <a class="header-anchor" href="#mcp-如何工作" aria-label="Permalink to “MCP 如何工作”">​</a></h2><ul><li>MCP Hosts: Hosts 是指 LLM 启动连接的应用程序，像 Cursor, Claude Desktop、<a href="https://link.zhihu.com/?target=https%3A//github.com/cline/cline" target="_blank" rel="noreferrer">Cline</a> 这样的应用程序。</li><li>MCP Clients: 客户端是用来在 Hosts 应用程序内维护与 Server 之间 1:1 连接。</li><li>MCP Servers: 通过标准化的协议，为 Client 端提供上下文、工具和提示。</li><li>Local Data Sources: 本地的文件、数据库和 API。</li><li>Remote Services: 外部的文件、数据库和 API。</li></ul><p>整个 MCP 协议核心的在于 Server，因为 Host 和 Client 相信熟悉计算机网络的都不会陌生，非常好理解，但是 Server 如何理解呢？</p><p>看看 Cursor 的 AI Agent 发展过程，我们会发现整个 AI 自动化的过程发展会是从 Chat 到 Composer 再进化到完整的 AI Agent。</p><p>AI Chat 只是提供建议，如何将 AI 的 response 转化为行为和最终的结果，全部依靠人类，例如手动复制粘贴，或者进行某些修改。</p><p>AI Composer 是可以自动修改代码，但是需要人类参与和确认，并且无法做到除了修改代码之外的其它操作。</p><p>AI Agent 是一个完全的自动化程序，未来完全可以做到自动读取 Figma 的图片，自动生产代码，自动读取日志，自动调试代码，自动 push 代码到 GitHub。</p><p>而 MCP Server 就是为了实现 AI Agent 的自动化而存在的，它是一个中间层，告诉 AI Agent 目前存在哪些服务，哪些 API，哪些数据源，AI Agent 可以根据 Server 提供的信息来决定是否调用某个服务，然后通过 Function Calling 来执行函数。</p><h2 id="相关资源" tabindex="-1">相关资源 <a class="header-anchor" href="#相关资源" aria-label="Permalink to “相关资源”">​</a></h2><h3 id="mcp-官方资源" tabindex="-1">MCP 官方资源 <a class="header-anchor" href="#mcp-官方资源" aria-label="Permalink to “MCP 官方资源”">​</a></h3><ul><li><a href="https://link.zhihu.com/?target=https%3A//github.com/modelcontextprotocol" target="_blank" rel="noreferrer">官方的开源组织 Model Context Protocol</a>。</li><li><a href="https://link.zhihu.com/?target=https%3A//guangzhengli.com/blog/zh/model-context-protocol/%5Bmodelcontextprotocol%5D(https%3A//modelcontextprotocol.io/introduction)" target="_blank" rel="noreferrer">官方的文档 modelcontextprotocol</a>。</li><li><a href="https://link.zhihu.com/?target=https%3A//github.com/modelcontextprotocol/servers" target="_blank" rel="noreferrer">官方的 MCP Server 列表</a></li><li><a href="https://link.zhihu.com/?target=https%3A//www.anthropic.com/news/model-context-protocol" target="_blank" rel="noreferrer">Claude Blog</a></li></ul><h3 id="社区的-mcp-server-的列表" tabindex="-1">社区的 MCP Server 的列表 <a class="header-anchor" href="#社区的-mcp-server-的列表" aria-label="Permalink to “社区的 MCP Server 的列表”">​</a></h3><ul><li><a href="https://link.zhihu.com/?target=https%3A//cursor.directory/" target="_blank" rel="noreferrer">Cursor Directory</a></li><li><a href="https://link.zhihu.com/?target=https%3A//www.pulsemcp.com/" target="_blank" rel="noreferrer">Pulsemcp</a></li><li><a href="https://link.zhihu.com/?target=https%3A//glama.ai/mcp/servers" target="_blank" rel="noreferrer">Glama MCP Servers</a></li></ul>`,73)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};